package td4;

import main.Automata;
import main.Automata.Command;
import main.java.td4.StopState;

public class App {
    public String getGreeting() {
        return "Hello World!";
    }

    public static void main(String[] args) {
        Automata automata = new Automata();
        automata.setState ( new StopState( automata ));
        automata.setCurrentCommand( Command.PLAY );
        automata.request();
        automata.setCurrentCommand( Command.STOP );
        automata.request();
        automata.setCurrentCommand( Command.REWIND );
        automata.request();
        automata.setCurrentCommand(Command.PLAY );
        automata.request();
        automata.setCurrentCommand( Command.STOP );
        automata.request();
    }
}
